using System.Text.RegularExpressions;

namespace StockTracker.Infrastructure.Storage;

/// <summary>Keys are generated by the app ("products/{id}/{photoId}.webp"); anything else is refused.</summary>
public static partial class FileKeys
{
    public static bool IsValid(string? key) =>
        key is { Length: > 0 and <= 300 } && SafeKey().IsMatch(key) && !key.Contains("..", StringComparison.Ordinal);

    public static string ContentTypeOf(string key) =>
        Path.GetExtension(key).ToLowerInvariant() switch
        {
            ".webp" => "image/webp",
            ".jpg" or ".jpeg" => "image/jpeg",
            ".png" => "image/png",
            _ => "application/octet-stream",
        };

    [GeneratedRegex("^[a-z0-9][a-z0-9/_.-]*$")]
    private static partial Regex SafeKey();
}
